/**
 * JSONL 编解码：每行一条完整 JSON，UTF-8。
 * 解码器处理半包、粘包、多字节字符跨 chunk、超长行丢弃。
 * 纯 TS 实现（仅依赖 TextDecoder），Node 与浏览器/Electron 两侧共用。
 */

// A restored thread is one JSONL record and may contain years of turns. Keep a
// bounded limit, but don't silently discard ordinary long conversation history.
export const DEFAULT_MAX_LINE_BYTES = 64 * 1024 * 1024;

/** 报错时回带的原文长度：够定位就行，不把整行塞进日志。 */
const RAW_PREVIEW_CHARS = 200;

export type JsonlDecodeResult =
  | { ok: true; value: unknown }
  | { ok: false; error: 'invalid-json' | 'line-too-large'; raw: string };

export interface JsonlDecoderOptions {
  maxLineBytes?: number;
}

export class JsonlDecoder {
  /** 累积中的半行，按分片存放：只在遇到换行时 join 一次，不用 `+=` 反复展开长字符串。 */
  private pending: string[] = [];
  /** `pending` 拼接后的 UTF-8 字节数，增量维护。长响应按 64 KiB 分片到达时不能每次重新扫一遍。 */
  private pendingBytes = 0;
  /** `pending` 末尾的 UTF-16 code unit，用来修正被调用方切开的代理对（见 append）。 */
  private pendingTail = 0;
  private overflowing = false;
  private readonly maxLineBytes: number;
  private readonly textDecoder = new TextDecoder('utf-8');

  constructor(options: JsonlDecoderOptions = {}) {
    this.maxLineBytes = options.maxLineBytes ?? DEFAULT_MAX_LINE_BYTES;
  }

  /** 喂入一段数据，返回本次解析出的完整行（可能为空数组）。 */
  push(chunk: Uint8Array | string): JsonlDecodeResult[] {
    const text =
      typeof chunk === 'string'
        ? chunk
        : this.textDecoder.decode(chunk, { stream: true });

    const results: JsonlDecodeResult[] = [];
    // 只在本次 chunk 里找换行：已缓存的分片上一轮扫过，里面不可能再有换行。
    let cursor = 0;
    for (;;) {
      const newline = text.indexOf('\n', cursor);
      if (newline < 0) break;
      const segment = text.slice(cursor, newline);
      cursor = newline + 1;

      if (this.overflowing) {
        // 之前的超长行到此结束，丢弃它
        this.overflowing = false;
        continue;
      }
      const { line, bytes } = this.takeLine(segment);
      const hasCr = line.endsWith('\r');
      const trimmed = hasCr ? line.slice(0, -1) : line;
      if (trimmed.trim().length === 0) continue;
      if ((hasCr ? bytes - 1 : bytes) > this.maxLineBytes) {
        results.push({ ok: false, error: 'line-too-large', raw: trimmed.slice(0, RAW_PREVIEW_CHARS) });
        continue;
      }
      try {
        results.push({ ok: true, value: JSON.parse(trimmed) });
      } catch {
        results.push({ ok: false, error: 'invalid-json', raw: trimmed.slice(0, RAW_PREVIEW_CHARS) });
      }
    }

    // 丢弃模式下的残留只是超长行的尾巴，不必留着占内存
    if (this.overflowing) return results;
    this.append(text.slice(cursor));
    if (this.pendingBytes > this.maxLineBytes) {
      // 半行已超长：进入丢弃模式，直到下一个换行
      results.push({ ok: false, error: 'line-too-large', raw: this.pendingPreview() });
      this.reset();
      this.overflowing = true;
    }
    return results;
  }

  /** 流结束时调用：把残留的最后一行（无换行结尾）也解析出来。 */
  flush(): JsonlDecodeResult[] {
    // 流已结束，丢弃模式再没有「下一个换行」可等
    this.overflowing = false;
    if (this.pending.length === 0) return [];
    const rest = this.pending.join('');
    this.reset();
    if (rest.trim().length === 0) return [];
    return this.push(`${rest}\n`);
  }

  /** 取出完整一行（已缓存的分片 + 本次 chunk 里换行前的部分），并清空缓存。 */
  private takeLine(segment: string): { line: string; bytes: number } {
    // 整行落在同一个 chunk 里是最常见的情况，不需要经过缓存
    if (this.pending.length === 0) return { line: segment, bytes: utf8ByteLength(segment) };
    this.append(segment);
    const line = this.pending.join('');
    const bytes = this.pendingBytes;
    this.reset();
    return { line, bytes };
  }

  private append(segment: string): void {
    if (segment.length === 0) return;
    let bytes = utf8ByteLength(segment);
    // push(string) 的调用方可能把代理对切在分片边界上：分开算是 4 + 3 字节，
    // 拼起来高低位配成一个 4 字节码点，得把多算的 3 字节减掉。
    // （Uint8Array 走 TextDecoder 流式解码，它自己会攒够字节，不会切开代理对。）
    if (isHighSurrogate(this.pendingTail) && isLowSurrogate(segment.charCodeAt(0))) bytes -= 3;
    this.pending.push(segment);
    this.pendingBytes += bytes;
    this.pendingTail = segment.charCodeAt(segment.length - 1);
  }

  private reset(): void {
    this.pending = [];
    this.pendingBytes = 0;
    this.pendingTail = 0;
  }

  /** 超长行只回报开头一小段，不为了报错去 join 整个缓存。 */
  private pendingPreview(): string {
    let preview = '';
    for (const segment of this.pending) {
      preview += segment.slice(0, RAW_PREVIEW_CHARS - preview.length);
      if (preview.length >= RAW_PREVIEW_CHARS) break;
    }
    return preview;
  }
}

/** 编码一条消息为一行 JSON（含结尾换行）。JSON.stringify 会转义字符串内换行，行内不会出现裸换行。 */
export function encodeJsonLine(value: unknown): string {
  const text = JSON.stringify(value);
  if (text === undefined) throw new TypeError('JSONL: value is not serializable');
  return `${text}\n`;
}

export function utf8ByteLength(text: string): number {
  let bytes = 0;
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code < 0x80) bytes += 1;
    else if (code < 0x800) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff) {
      // 代理对：算 4 字节，跳过低位
      bytes += 4;
      i++;
    } else bytes += 3;
  }
  return bytes;
}

function isHighSurrogate(code: number): boolean {
  return code >= 0xd800 && code <= 0xdbff;
}

function isLowSurrogate(code: number): boolean {
  return code >= 0xdc00 && code <= 0xdfff;
}
